"""Bounded pre-open Mystery Box diagnostic copies; never runtime authority."""
from __future__ import annotations

from datetime import datetime, timezone
import hashlib
import io
import json
import math
import os
from pathlib import Path
import re
import stat
import threading
import time
from typing import Any

from PIL import Image
from visionstudio_durable_io import atomic_write_bytes

EVIDENCE_FOLDER = Path("controller") / "mystery-box-evidence"
MAX_SNAPSHOTS = 3
MAX_FRAME_BYTES = 12 * 1024 * 1024
MAX_METADATA_BYTES = 32_000
MAX_FRAME_PIXELS = 16_000_000
BOX_TYPES = ("brown", "silver", "gold", "rainbow", "unknown")
_SHA = re.compile(r"[0-9a-f]{64}\Z")
_SESSION = re.compile(r"[0-9a-f]{32}\Z")
_SOURCES = {"stable-preopen-pixels", "retained-result-count", "unavailable"}
_PIXEL_REASONS = {"unsupported_image", "overlapping_presence", "ambiguous_layout", "unclassified_presence",
                  "no_complete_layout", "unexplained_presence", "unstable_frames"}
_LOCK = threading.RLock()


def _canonical(value: Any) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("utf-8")


def _integer(value: Any, maximum: int, *, minimum: int = 0) -> int:
    if type(value) is not int or not minimum <= value <= maximum:
        raise ValueError("Invalid Mystery Box diagnostic integer")
    return value


def _hash(value: Any) -> str:
    if not isinstance(value, str) or _SHA.fullmatch(value) is None:
        raise ValueError("Invalid Mystery Box diagnostic hash")
    return value


def _counts(value: Any) -> dict[str, int]:
    if not isinstance(value, dict) or set(value) != set(BOX_TYPES):
        raise ValueError("Invalid Mystery Box diagnostic counts")
    result = {name: _integer(value[name], 1000) for name in BOX_TYPES}
    if sum(result.values()) > 1000:
        raise ValueError("Invalid Mystery Box diagnostic count total")
    return result


def _number(value: Any, minimum: float, maximum: float) -> int | float:
    if type(value) not in {int, float} or not minimum <= value <= maximum or (type(value) is float and not math.isfinite(value)):
        raise ValueError("Invalid Mystery Box diagnostic number")
    return value


def _png_dimensions(png: bytes) -> list[int]:
    if not isinstance(png, bytes) or not 0 < len(png) <= MAX_FRAME_BYTES or not png.startswith(b"\x89PNG\r\n\x1a\n"):
        raise ValueError("Invalid Mystery Box diagnostic PNG")
    try:
        with Image.open(io.BytesIO(png)) as image:
            width, height = image.size
            if image.format != "PNG" or not (1 <= width <= 8192 and 1 <= height <= 8192) or width * height > MAX_FRAME_PIXELS:
                raise ValueError("Oversized Mystery Box diagnostic PNG")
            image.verify()
    except (OSError, SyntaxError, Image.DecompressionBombError) as exc:
        raise ValueError("Invalid Mystery Box diagnostic PNG") from exc
    return [width, height]


def _safe_source(metadata: Any) -> dict[str, Any]:
    if not isinstance(metadata, dict) or metadata.get("schema_version") != 2 or metadata.get("classifier_version") != "stage-bound-hsv-v2":
        raise ValueError("Unsupported Mystery Box diagnostic source")
    if metadata.get("stage_id") != "open-all-boxes" or not isinstance(metadata.get("session_id"), str) or not _SESSION.fullmatch(metadata["session_id"]):
        raise ValueError("Invalid Mystery Box diagnostic stage or Session")
    result = {"schema_version": 2, "classifier_version": "stage-bound-hsv-v2",
              "stage_id": "open-all-boxes", "session_id": metadata["session_id"],
              "observation_number": _integer(metadata.get("observation_number"), 10**9, minimum=1),
              "frame_sha256": _hash(metadata.get("frame_sha256"))}
    for name in ("exact_scene", "complete_layout", "absence_crosscheck_passed", "image_pixels_only", "resolved_count_known", "result_box_count_known", "result_count_conflict"):
        if name in metadata:
            if type(metadata[name]) is not bool:
                raise ValueError("Invalid Mystery Box diagnostic flag")
            result[name] = metadata[name]
    for name in ("resolved_count", "result_box_count", "visible_slot_count", "component_visible_slot_count"):
        if name in metadata:
            result[name] = None if metadata[name] is None else _integer(metadata[name], 1000)
    if "candidate_visible_count" in metadata:
        result["candidate_visible_count"] = None if metadata["candidate_visible_count"] is None else _integer(metadata["candidate_visible_count"], 5, minimum=1)
    for name in ("pixel_detection_reason", "incomplete_reason"):
        if name in metadata:
            value = metadata[name]
            if value is None or isinstance(value, str) and value in _PIXEL_REASONS:
                result[name] = value
    if "count_source" in metadata:
        if not isinstance(metadata["count_source"], str) or metadata["count_source"] not in _SOURCES:
            raise ValueError("Invalid Mystery Box diagnostic count source")
        result["count_source"] = metadata["count_source"]
    for name in ("boxes", "resolved_boxes", "classified_boxes"):
        if name in metadata:
            result[name] = _counts(metadata[name])
    if "layout_id" in metadata:
        if metadata["layout_id"] is not None and (not isinstance(metadata["layout_id"], str) or metadata["layout_id"] not in {"verified-3", "verified-5", "generic-components"}):
            raise ValueError("Invalid Mystery Box diagnostic layout")
        result["layout_id"] = metadata["layout_id"]
    if "layout_vertical_offset" in metadata:
        result["layout_vertical_offset"] = None if metadata["layout_vertical_offset"] is None else _number(metadata["layout_vertical_offset"], -.2, .2)
    for name in ("mission_sha256", "integrity_sha256", "evidence_integrity_sha256", "recovery_binding_sha256"):
        if name in metadata:
            result[name] = _hash(metadata[name])
    raw_slots = metadata.get("slots")
    if raw_slots is not None:
        if not isinstance(raw_slots, list) or len(raw_slots) > 5:
            raise ValueError("Invalid Mystery Box diagnostic slots")
        slots = []
        for row in raw_slots:
            if not isinstance(row, dict):
                raise ValueError("Invalid Mystery Box diagnostic slot")
            safe = {"slot": _integer(row.get("slot"), 5, minimum=1)}
            if not isinstance(row.get("classification"), str) or row.get("classification") not in BOX_TYPES or type(row.get("present")) is not bool:
                raise ValueError("Invalid Mystery Box diagnostic slot classification")
            safe.update(classification=row["classification"], present=row["present"])
            center = row.get("center")
            if center is not None:
                if not isinstance(center, (list, tuple)) or len(center) != 2:
                    raise ValueError("Invalid Mystery Box diagnostic center")
                safe["center"] = [_number(value, 0, 1) for value in center]
            for key in ("profile_l1", "profile_margin", "foreground_coverage", "saturation_median", "value_median"):
                if key in row:
                    safe[key] = None if row[key] is None else _number(row[key], -2 if key == "profile_margin" else 0, 2)
            if "hard_gate_passed" in row:
                if type(row["hard_gate_passed"]) is not bool:
                    raise ValueError("Invalid Mystery Box diagnostic slot flag")
                safe["hard_gate_passed"] = row["hard_gate_passed"]
            if "component_support" in row:
                safe["component_support"] = _integer(row["component_support"], 10_000)
            slots.append(safe)
        result["slots"] = slots
    if "pixel_stability" in metadata:
        value = metadata["pixel_stability"]
        if not isinstance(value, dict) or type(value.get("stable")) is not bool:
            raise ValueError("Invalid Mystery Box diagnostic stability")
        safe = {"stable": value["stable"], "sample_count": _integer(value.get("sample_count"), 3, minimum=1)}
        for key, validator in (("matching_observations", lambda item: _integer(item, 10**9, minimum=1)),
                               ("matching_frame_sha256", _hash)):
            rows = value.get(key, [])
            if not isinstance(rows, list) or len(rows) > 2:
                raise ValueError("Invalid Mystery Box diagnostic matching frames")
            safe[key] = [validator(item) for item in rows]
        if "last_observation_number" in value:
            safe["last_observation_number"] = _integer(value["last_observation_number"], 10**9, minimum=1)
        if "last_frame_sha256" in value:
            safe["last_frame_sha256"] = _hash(value["last_frame_sha256"])
        result["pixel_stability"] = safe
    return result


def _read_regular(path: Path, maximum: int) -> bytes:
    before = os.stat(path, follow_symlinks=False)
    if not stat.S_ISREG(before.st_mode) or before.st_size > maximum:
        raise ValueError("Invalid Mystery Box diagnostic file")
    with path.open("rb") as source:
        opened = os.fstat(source.fileno())
        if not stat.S_ISREG(opened.st_mode) or (opened.st_ino, opened.st_dev) != (before.st_ino, before.st_dev) or opened.st_size > maximum:
            raise ValueError("Mystery Box diagnostic file changed")
        content = source.read(maximum + 1)
    if len(content) > maximum:
        raise ValueError("Oversized Mystery Box diagnostic file")
    return content


def _read_slot(folder: Path, slot: int) -> dict[str, Any]:
    try:
        metadata = json.loads(_read_regular(folder / f"{slot}.json", MAX_METADATA_BYTES))
    except (RecursionError, UnicodeError) as exc:
        raise ValueError("Invalid stored Mystery Box diagnostic JSON") from exc
    if not isinstance(metadata, dict) or metadata.get("format") != "axiom-mystery-box-evidence" or type(metadata.get("storage_schema_version")) is not int or metadata.get("storage_schema_version") != 1 or metadata.get("input_authority") is not False or type(metadata.get("slot")) is not int or metadata.get("slot") != slot:
        raise ValueError("Invalid stored Mystery Box diagnostic metadata")
    digest = metadata.get("metadata_sha256")
    body = {name: value for name, value in metadata.items() if name != "metadata_sha256"}
    if _hash(digest) != hashlib.sha256(_canonical(body)).hexdigest():
        raise ValueError("Mystery Box diagnostic metadata hash mismatch")
    safe = _safe_source(metadata)
    storage_fields = {"format", "storage_schema_version", "snapshot_id", "slot", "saved_at_unix_ns", "saved_at", "capture_size", "frame_bytes", "input_authority", "metadata_sha256"}
    if set(metadata) != set(safe) | storage_fields:
        raise ValueError("Unexpected stored Mystery Box diagnostic fields")
    if any(metadata.get(name) != value for name, value in safe.items()):
        raise ValueError("Mystery Box diagnostic source changed")
    png = _read_regular(folder / f"{slot}.png", MAX_FRAME_BYTES)
    if hashlib.sha256(png).hexdigest() != safe["frame_sha256"] or metadata.get("frame_bytes") != len(png) or metadata.get("capture_size") != _png_dimensions(png):
        raise ValueError("Mystery Box diagnostic PNG binding mismatch")
    _integer(metadata.get("saved_at_unix_ns"), 2**63 - 1, minimum=1)
    stamp = metadata.get("saved_at")
    if not isinstance(stamp, str) or len(stamp) > 40:
        raise ValueError("Invalid Mystery Box diagnostic timestamp")
    datetime.fromisoformat(stamp)
    expected_id = hashlib.sha256(_canonical([safe["session_id"], safe["observation_number"], safe["frame_sha256"]])).hexdigest()[:32]
    if metadata.get("snapshot_id") != expected_id:
        raise ValueError("Mystery Box diagnostic snapshot identity mismatch")
    return {"metadata": metadata, "png": png}


def save_mystery_box_evidence(data_root: Path, png_bytes: bytes, metadata: dict[str, Any]) -> dict[str, Any]:
    """Persist at most three exact pre-open frames, without changing runtime state."""
    safe = _safe_source(metadata)
    dimensions = _png_dimensions(png_bytes)
    if safe["frame_sha256"] != hashlib.sha256(png_bytes).hexdigest():
        raise ValueError("Mystery Box diagnostic PNG hash differs from its observation")
    snapshot_id = hashlib.sha256(_canonical([safe["session_id"], safe["observation_number"], safe["frame_sha256"]])).hexdigest()[:32]
    folder = Path(data_root) / EVIDENCE_FOLDER
    with _LOCK:
        folder.mkdir(parents=True, exist_ok=True)
        prior = []
        for slot in range(1, MAX_SNAPSHOTS + 1):
            try:
                row = _read_slot(folder, slot)
                if row["metadata"]["snapshot_id"] == snapshot_id:
                    return dict(row["metadata"])
                prior.append((row["metadata"]["saved_at_unix_ns"], slot))
            except (OSError, ValueError, TypeError, RecursionError):
                prior.append((0, slot))
        _age, slot = min(prior)
        result = {**safe, "format": "axiom-mystery-box-evidence", "storage_schema_version": 1,
                  "snapshot_id": snapshot_id, "slot": slot, "saved_at_unix_ns": time.time_ns(),
                  "saved_at": datetime.now(timezone.utc).isoformat(),
                  "capture_size": dimensions, "frame_bytes": len(png_bytes), "input_authority": False}
        result["metadata_sha256"] = hashlib.sha256(_canonical(result)).hexdigest()
        encoded = _canonical(result) + b"\n"
        if len(encoded) > MAX_METADATA_BYTES:
            raise ValueError("Oversized Mystery Box diagnostic metadata")
        # Publish the PNG before its hash-bound metadata. An interrupted pair
        # fails validation; no reader can mistake the new PNG for the old frame.
        atomic_write_bytes(folder / f"{slot}.png", png_bytes)
        atomic_write_bytes(folder / f"{slot}.json", encoded)
    return result


def load_mystery_box_evidence(data_root: Path) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Read validated fixed slots and report missing/corrupt snapshots as unknown."""
    folder = Path(data_root) / EVIDENCE_FOLDER
    snapshots = []
    present = invalid = 0
    for slot in range(1, MAX_SNAPSHOTS + 1):
        if not (folder / f"{slot}.json").exists() and not (folder / f"{slot}.png").exists():
            continue
        present += 1
        try:
            snapshots.append(_read_slot(folder, slot))
        except (OSError, ValueError, TypeError, RecursionError):
            invalid += 1
    snapshots.sort(key=lambda row: row["metadata"]["saved_at_unix_ns"], reverse=True)
    coverage = {"schema_version": 1, "scope": "latest retained pre-open Mystery Box diagnostic snapshots",
                "max_snapshots": MAX_SNAPSHOTS, "slots_present": present,
                "snapshots_returned": len(snapshots), "invalid_slots": invalid,
                "missing_slots": MAX_SNAPSHOTS - present, "complete_history": False,
                "atomic_snapshot": False, "input_authority": False,
                "missing_evidence_means": "unknown", "fields_are_whitelisted": True}
    return snapshots, coverage

